        assert.deepEqual(await readAll(await store.get(key)), Buffer.from("staged bytes"));
        assert.deepEqual(await store.head(key), { size: 12 });
        assert.deepEqual(
          (await listRaw()).map((n) => n.split("/").at(-1)),
