        store.put(key(), Buffer.from("x"), 10),
        store.get(key()),
        store.head(key()),
        store.sweepStaleTemporaries(1, () => undefined),
      ]) {
        const err = await (attempt as Promise<unknown>).then(
          () => null,
          (e: unknown) => e,
